window.receiveProjectSource({"path": "test/unit/microservices/event_synthesis/services/test_qa_report_llm.py", "lines": ["\"\"\"Unit tests for ``QAReportGraderClient`` (DAT-7639).", "", "Mirrors ``test_merge_llm.py``: mock ``APIHelper.execute_api_request`` with", "``{\"choices\":[{\"content\": json.dumps(body)}]}``. Covers the provider chain,", "the batch double-failure contract (RE-RAISE, not outage), semantic grade<->sample", "identity validation over the EFFECTIVE (prepared) set, and the pure", "``prepare_input`` context-budget enforcement.", "\"\"\"", "", "from __future__ import annotations", "", "import json", "from datetime import UTC, datetime", "from typing import Any", "from uuid import UUID, uuid4", "", "import pytest", "", "from common.exceptions import AIServiceException", "from common.models.enums import ChatModel", "from common.services.llm_chat import LLMChatParams", "from microservices.event_synthesis.exceptions import EventSynthesisConfigurationException", "from microservices.event_synthesis.repositories.qa_sample import (", "    QASampleChange,", "    QASampleDoc,", "    QASampleEntity,", "    QASampleRow,", "    derive_entity_check_status,", ")", "from microservices.event_synthesis.services import qa_report_llm as qa_report_llm_mod", "from microservices.event_synthesis.services.qa_report_flags import is_flagged", "from microservices.event_synthesis.services.qa_report_llm import (", "    QAReportGraderClient,", "    entity_evidence_reached_grader,", ")", "from microservices.event_synthesis.services.qa_report_types import (", "    PreparedQAReportInput,", "    QAReportInput,", ")", "", "pytestmark = pytest.mark.unit", "", "_BASE = datetime(2026, 7, 1, 12, 0, 0, tzinfo=UTC)", "", "", "def _params(primary: ChatModel = ChatModel.GPT_6_LUNA) -> LLMChatParams:", "    return LLMChatParams(", "        microservice_id=\"test-microservice-id\",", "        endpoint_path=\"/api/v1/ai/llm-chat\",", "        default_chat_model=primary,", "        default_reasoning=\"low\",", "        default_verbosity=\"low\",", "        default_max_tokens=4096,", "        total_timeout_s=30.0,", "        connect_timeout_s=10.0,", "        socket_read_timeout_s=40.0,", "        socket_connect_timeout_s=10.0,", "    )", "", "", "def _grader(", "    *side_effects: Any,", "    max_input_chars: int = 1_000_000,", "    primary: ChatModel = ChatModel.GPT_6_LUNA,", ") -> tuple[QAReportGraderClient, Any]:", "    from unittest.mock import AsyncMock, Mock", "", "    def _normalize(item: Any) -> Any:", "        if isinstance(item, BaseException):", "            return item", "        return (item, 200, {})", "", "    api_helper = Mock()", "    api_helper.execute_api_request = AsyncMock(side_effect=[_normalize(s) for s in side_effects])", "    client = QAReportGraderClient(", "        api_helper=api_helper,", "        params=_params(primary),", "        fallback_chat_model=ChatModel.CLAUDE_HAIKU_4_5,", "        openai_api_key=\"sk-openai\",", "        anthropic_api_key=\"sk-anthropic\",", "        max_input_chars=max_input_chars,", "        fallback_total_timeout=150.0,", "    )", "    return client, api_helper", "", "", "def _captured_body(api_helper: Any, idx: int = 0) -> dict[str, Any]:", "    \"\"\"Return the request body of the n-th execute_api_request call (0-indexed).\"\"\"", "    return api_helper.execute_api_request.call_args_list[idx].kwargs[\"body\"]", "", "", "def _entity(*, name: str = \"Acme Corporation\", kind: str = \"CVW\") -> QASampleEntity:", "    \"\"\"DAT-8294: ``display_name`` / ``entity_type`` are REQUIRED on the prompt DTO.\"\"\"", "    return QASampleEntity(entity_id=uuid4(), role=\"subject\", display_name=name, entity_type=kind)", "", "", "def _row(", "    event_class: str = \"create\",", "    eid: UUID | None = None,", "    *,", "    summary: str = \"s\",", "    docs: int = 0,", "    entities: int = 0,", "    changes: int = 0,", "    entity_name: str = \"Acme Corporation\",", ") -> QASampleRow:", "    return QASampleRow(", "        event_id=eid or uuid4(),", "        first_detected_on=_BASE,", "        event_class=event_class,  # type: ignore[arg-type]", "        summary=summary,", "        key_details=\"{}\",", "        docs=[", "            QASampleDoc(document_id=i, source_tier=1, article_type=\"news\", title=\"t\")", "            for i in range(docs)", "        ],", "        # DAT-8294: display_name / entity_type are REQUIRED on the prompt DTO.", "        entities=[_entity(name=entity_name) for _ in range(entities)],", "        changes=[QASampleChange(change_type=\"created\", changed_at=_BASE) for _ in range(changes)],", "    )", "", "", "#: DAT-8294 review. The per-entity name cap in ``_build_row`` counts PYTHON", "#: characters; the context budget in ``prepare_input`` measures SERIALIZED JSON.", "#: The two units are not interchangeable, so 80 plain letters is NOT the largest", "#: name the cap admits: 80 ASCII characters serialize to 82 (the quotes), 80", "#: quotes or backslashes to 162, and 80 JSON-escaped control characters to 482 --", "#: ~5.9x the plain-letter payload. ``ent.entities.display_name`` is an unbounded", "#: ``Text`` column, so the boundary fixture uses the escaping maximum rather than", "#: letters. U+001F (unit separator) and not NUL: Postgres ``text`` cannot store a", "#: NUL byte, so a NUL name is not one the sampler could ever read back.", "_MAX_EXPANSION_NAME = \"\\x1f\" * 80", "", "", "def _prepared(rows: list[QASampleRow]) -> PreparedQAReportInput:", "    return PreparedQAReportInput(events=list(rows), dropped_event_ids=[], truncated_fields=0)", "", "", "def _response(body: dict) -> dict[str, Any]:", "    return {\"choices\": [{\"index\": 0, \"role\": \"assistant\", \"content\": json.dumps(body)}]}", "", "", "def _raw_response(content: str) -> dict[str, Any]:", "    return {\"choices\": [{\"index\": 0, \"role\": \"assistant\", \"content\": content}]}", "", "", "def _valid_body(rows: list[QASampleRow], duplicate_pairs: list[dict] | None = None) -> dict:", "    return {", "        \"per_event\": [", "            {", "                \"event_id\": str(r.event_id),", "                \"event_valid\": True,", "                # Gradable only with >=2 docs to compare; else not applicable (null).", "                \"merge_correct\": True if (r.event_class == \"merge\" and len(r.docs) >= 2) else None,", "                # DAT-8294: applicable ONLY where entity identity reached the grader;", "                # null otherwise. ``_validate_semantic`` enforces both directions, so a", "                # canned body ignoring this would be rejected outright.", "                \"entity_linkage_plausible\": True if r.entities else None,", "                \"entity_linkage_explanation\": None,", "                \"issues\": [],", "                \"explanation\": \"looks correct\",", "                \"confidence\": 0.9,", "            }", "            for r in rows", "        ],", "        \"duplicate_pairs\": duplicate_pairs or [],", "    }", "", "", "# ---------------------------------------------------------------- happy path", "", "", "async def test_primary_success_parses_all_three_checks() -> None:", "    rows = [_row(\"create\"), _row(\"merge\", docs=2)]", "    dup = {", "        \"event_id_a\": str(rows[0].event_id),", "        \"event_id_b\": str(rows[1].event_id),", "        \"same_event\": True,", "        \"confidence\": 0.8,", "        \"explanation\": \"same real-world event\",", "    }", "    grader, api_helper = _grader(_response(_valid_body(rows, [dup])))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert result.fallback_used is False", "    assert result.chat_model_used == ChatModel.GPT_6_LUNA.value", "    assert len(result.output.per_event) == 2", "    # validity + merge-correctness present, and a cross-sample duplicate flagged.", "    assert {g.merge_correct for g in result.output.per_event} == {None, True}", "    assert len(result.output.duplicate_pairs) == 1", "    assert api_helper.execute_api_request.await_count == 1", "", "", "def _cut_off(rows: list[QASampleRow]) -> str:", "    \"\"\"A reply cut off mid-object, as at max_tokens: json_repair would close it.\"\"\"", "    serialized = json.dumps(_valid_body(rows))", "    return serialized[: len(serialized) // 2]", "", "", "async def test_a_repaired_primary_reply_falls_back_instead_of_being_graded(", "    monkeypatch: pytest.MonkeyPatch,", ") -> None:", "    \"\"\"DAT-10994: a cut-off reply is rejected, not patched into a partial grade.", "", "    The rejection leaves one structured WARNING naming the model, so cut-offs can", "    be counted after the max_tokens raise.", "    \"\"\"", "    rows = [_row(\"create\"), _row(\"merge\")]", "    grader, api_helper = _grader(_raw_response(_cut_off(rows)), _response(_valid_body(rows)))", "    warned: list[dict[str, Any]] = []", "    monkeypatch.setattr(", "        qa_report_llm_mod.logger,", "        \"warning\",", "        lambda event, **kw: warned.append({\"event\": event, **kw}),", "    )", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert api_helper.execute_api_request.await_count == 2", "    assert result.fallback_used is True", "    assert len(result.output.per_event) == 2", "    rejected = [w for w in warned if w.get(\"reason\") == \"json_repaired\"]", "    assert len(rejected) == 1", "    assert rejected[0][\"chat_model\"] == ChatModel.GPT_6_LUNA.value", "", "", "async def test_a_repaired_fallback_reply_fails_the_batch() -> None:", "    rows = [_row(\"create\"), _row(\"merge\")]", "    primary_err = AIServiceException(\"503 upstream\", http_response_code=503)", "    grader, _ = _grader(primary_err, _raw_response(_cut_off(rows)))", "", "    with pytest.raises(AIServiceException, match=\"could not be parsed\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_a_fenced_but_valid_reply_is_still_accepted() -> None:", "    rows = [_row(\"create\")]", "    fenced = \"```json\\n\" + json.dumps(_valid_body(rows)) + \"\\n```\"", "    grader, _ = _grader(_raw_response(fenced))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert result.fallback_used is False", "    assert len(result.output.per_event) == 1", "", "", "async def test_a_raw_socket_timeout_falls_back_once_and_then_fails_the_batch() -> None:", "    \"\"\"DAT-10994: with retries off, aiohttp's own timeout still reaches the chain.", "", "    APIHelper's exhaustion wrapper is skipped when ``retry=False``, so the timeout", "    arrives unwrapped; ``raw_llm_chat_call`` must still turn it into an", "    AIServiceException, or the grader would neither fall back nor degrade.", "    \"\"\"", "    from aiohttp.client_exceptions import SocketTimeoutError", "", "    rows = [_row(\"create\")]", "    timeout = SocketTimeoutError(\"Timeout on reading data from socket\")", "    grader, api_helper = _grader(timeout, _response(_valid_body(rows)))", "    assert (await grader.grade(prepared=_prepared(rows))).fallback_used is True", "    assert api_helper.execute_api_request.await_count == 2  # the timeout is not retried", "", "    grader, api_helper = _grader(timeout, timeout)", "    with pytest.raises(AIServiceException, match=\"SocketTimeoutError\"):", "        await grader.grade(prepared=_prepared(rows))", "    assert api_helper.execute_api_request.await_count == 2", "", "", "async def test_each_provider_gets_one_request_with_its_own_timeout() -> None:", "    \"\"\"DAT-10994: no transport retries; the fallback runs under its own, longer limit.", "", "    A retried call starts over, so in QA three 60 s Sol attempts all timed out", "    before the fallback could start.", "    \"\"\"", "    rows = [_row(\"create\")]", "    primary_err = AIServiceException(\"timed out\", http_response_code=None)", "    grader, api_helper = _grader(primary_err, _response(_valid_body(rows)))", "", "    await grader.grade(prepared=_prepared(rows))", "", "    primary_call, fallback_call = api_helper.execute_api_request.call_args_list", "    assert primary_call.kwargs[\"retry\"] is False", "    assert fallback_call.kwargs[\"retry\"] is False", "    assert primary_call.kwargs[\"timeout\"].total == 30.0", "    assert fallback_call.kwargs[\"timeout\"].total == 150.0", "    # sock_read follows the call's limit, or a slow reply still dies at the shared 40 s.", "    assert fallback_call.kwargs[\"timeout\"].sock_read == 150.0", "", "", "# ----------------------------------------------------------- provider chain", "", "", "async def test_fallback_used_when_primary_raises() -> None:", "    rows = [_row(\"create\"), _row(\"merge\")]", "    primary_err = AIServiceException(\"503 upstream\", http_response_code=503)", "    grader, api_helper = _grader(primary_err, _response(_valid_body(rows)))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert result.fallback_used is True", "    assert result.chat_model_used == ChatModel.CLAUDE_HAIKU_4_5.value", "    assert api_helper.execute_api_request.await_count == 2", "", "", "async def test_the_fallback_asks_for_a_reasoning_level_claude_accepts() -> None:", "    \"\"\"The fallback is unusable if it asks for reasoning the model cannot take.", "", "    Accelerate rejects a reasoning request outright when the model's", "    ``ai_engines`` row says ``supports_reasoning = False``, so the configured", "    default cannot simply be forwarded to the Anthropic leg. Asserting on", "    ``fallback_used`` alone cannot see this -- the mock answers whatever it is", "    asked, which is why DAT-8777 shipped with a green suite.", "    \"\"\"", "    rows = [_row(\"create\"), _row(\"merge\")]", "    primary_err = AIServiceException(\"503 upstream\", http_response_code=503)", "    grader, api_helper = _grader(primary_err, _response(_valid_body(rows)))", "", "    await grader.grade(prepared=_prepared(rows))", "", "    fallback_body = _captured_body(api_helper, 1)", "    assert fallback_body[\"chat_model\"] == ChatModel.CLAUDE_HAIKU_4_5.value", "    assert fallback_body[\"reasoning\"] == \"none\"", "", "", "async def test_the_primary_still_gets_the_configured_reasoning_level() -> None:", "    \"\"\"Only models that cannot take reasoning are overridden.\"\"\"", "    rows = [_row(\"create\")]", "    grader, api_helper = _grader(_response(_valid_body(rows)))", "", "    await grader.grade(prepared=_prepared(rows))", "", "    primary_body = _captured_body(api_helper, 0)", "    assert primary_body[\"chat_model\"] == ChatModel.GPT_6_LUNA.value", "    assert primary_body[\"reasoning\"] == _params().default_reasoning", "", "", "async def test_double_failure_raises_ai_service_exception() -> None:", "    rows = [_row(\"create\")]", "    err1 = AIServiceException(\"primary 503\", http_response_code=503)", "    err2 = AIServiceException(\"fallback 503\", http_response_code=503)", "    grader, _ = _grader(err1, err2)", "", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "# ------------------------------------- provider chain with the deployed primary", "", "", "@pytest.mark.parametrize(", "    \"primary\",", "    [ChatModel.GPT_5_6_TERRA, ChatModel.GPT_6_1_SOL],", "    ids=lambda model: model.value,", ")", "@pytest.mark.parametrize(\"primary_fails\", [False, True], ids=[\"primary_ok\", \"primary_raises\"])", "async def test_provider_chain_request_payloads(primary: ChatModel, primary_fails: bool) -> None:", "    \"\"\"Primary {Terra, Sol} x {success, AIServiceException}, checked at the request body.", "", "    The primary goes out under its own name, at the configured ``low`` reasoning, with", "    the OpenAI key. On failure the fallback goes out as Claude at ``none`` reasoning", "    with the Anthropic key, and the result records the fallback.", "    \"\"\"", "    rows = [_row(\"create\"), _row(\"merge\")]", "    responses: list[Any] = [_response(_valid_body(rows))]", "    if primary_fails:", "        responses.insert(0, AIServiceException(\"401 invalid key\", http_response_code=401))", "    grader, api_helper = _grader(*responses, primary=primary)", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    primary_body = _captured_body(api_helper, 0)", "    assert primary_body[\"chat_model\"] == primary.value", "    assert primary_body[\"reasoning\"] == \"low\"", "    assert primary_body[\"api_key\"] == \"sk-openai\"", "    if not primary_fails:", "        assert api_helper.execute_api_request.await_count == 1", "        assert result.fallback_used is False", "        assert result.chat_model_used == primary.value", "        return", "", "    assert api_helper.execute_api_request.await_count == 2", "    fallback_body = _captured_body(api_helper, 1)", "    assert fallback_body[\"chat_model\"] == ChatModel.CLAUDE_HAIKU_4_5.value", "    assert fallback_body[\"reasoning\"] == \"none\"", "    assert fallback_body[\"api_key\"] == \"sk-anthropic\"", "    assert result.fallback_used is True", "    assert result.chat_model_used == ChatModel.CLAUDE_HAIKU_4_5.value", "", "", "async def test_sol_primary_double_failure_still_raises_for_the_degraded_path() -> None:", "    \"\"\"Both legs failing re-raises, which is what sends the CLI down the degraded path.\"\"\"", "    rows = [_row(\"create\")]", "    err1 = AIServiceException(\"primary 401\", http_response_code=401)", "    err2 = AIServiceException(\"fallback 503\", http_response_code=503)", "    grader, api_helper = _grader(err1, err2, primary=ChatModel.GPT_6_1_SOL)", "", "    with pytest.raises(AIServiceException, match=\"fallback 503\"):", "        await grader.grade(prepared=_prepared(rows))", "", "    assert _captured_body(api_helper, 0)[\"chat_model\"] == ChatModel.GPT_6_1_SOL.value", "    assert _captured_body(api_helper, 1)[\"chat_model\"] == ChatModel.CLAUDE_HAIKU_4_5.value", "", "", "async def test_from_config_wires_sol_primary_with_claude_fallback(", "    monkeypatch: pytest.MonkeyPatch,", ") -> None:", "    \"\"\"The deployed wiring, not a hand-built client.", "", "    With ``ESS_QA_REPORT_CHAT_MODEL`` unset, ``from_config`` yields a Sol primary at", "    ``low`` reasoning and a Claude fallback at ``none``.", "    \"\"\"", "    from unittest.mock import AsyncMock, Mock", "", "    from microservices.event_synthesis.config import config as ess_config", "", "    monkeypatch.delenv(\"ESS_QA_REPORT_CHAT_MODEL\", raising=False)", "    monkeypatch.delenv(\"ESS_QA_REPORT_TOTAL_TIMEOUT\", raising=False)", "    monkeypatch.delenv(\"ESS_QA_REPORT_FALLBACK_TOTAL_TIMEOUT\", raising=False)", "    rows = [_row(\"create\")]", "    api_helper = Mock()", "    api_helper.execute_api_request = AsyncMock(", "        side_effect=[", "            AIServiceException(\"401 invalid key\", http_response_code=401),", "            (_response(_valid_body(rows)), 200, {}),", "        ]", "    )", "    grader = QAReportGraderClient.from_config(", "        api_helper=api_helper,", "        config=ess_config,", "        job_config=ess_config.qa_report_job_config(),", "        openai_api_key=\"sk-openai\",", "        anthropic_api_key=\"sk-anthropic\",", "    )", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    primary_body = _captured_body(api_helper, 0)", "    fallback_body = _captured_body(api_helper, 1)", "    assert (primary_body[\"chat_model\"], primary_body[\"reasoning\"], primary_body[\"api_key\"]) == (", "        \"gpt-6.1-sol\",", "        \"low\",", "        \"sk-openai\",", "    )", "    assert (fallback_body[\"chat_model\"], fallback_body[\"reasoning\"], fallback_body[\"api_key\"]) == (", "        \"claude-haiku-4-5\",", "        \"none\",", "        \"sk-anthropic\",", "    )", "    assert result.fallback_used is True", "    assert result.chat_model_used == \"claude-haiku-4-5\"", "    # DAT-10994: the deployed limits, one request per provider.", "    primary_call, fallback_call = api_helper.execute_api_request.call_args_list", "    assert primary_body[\"max_tokens\"] == fallback_body[\"max_tokens\"] == 16384", "    assert (primary_call.kwargs[\"timeout\"].total, fallback_call.kwargs[\"timeout\"].total) == (", "        120.0,", "        150.0,", "    )", "    assert primary_call.kwargs[\"retry\"] is fallback_call.kwargs[\"retry\"] is False", "", "", "async def test_out_of_range_confidence_rejected() -> None:", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"confidence\"] = 1.5  # out of [0, 1]", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "# ------------------------------------------------- semantic identity checks", "", "", "async def test_missing_event_id_raises() -> None:", "    rows = [_row(\"create\"), _row(\"merge\")]", "    body = _valid_body([rows[0]])  # only grades one of two prepared events", "    grader, _ = _grader(_response(body), _response(body))", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_unknown_event_id_raises() -> None:", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"].append(", "        {", "            \"event_id\": str(uuid4()),  # not in the prepared sample", "            \"event_valid\": True,", "            \"merge_correct\": None,", "            \"issues\": [],", "            \"explanation\": \"x\",", "            \"confidence\": 0.5,", "        }", "    )", "    grader, _ = _grader(_response(body), _response(body))", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_duplicate_event_id_raises() -> None:", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"].append(dict(body[\"per_event\"][0]))  # same id twice", "    grader, _ = _grader(_response(body), _response(body))", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_self_paired_duplicate_raises() -> None:", "    rows = [_row(\"create\"), _row(\"merge\")]", "    dup = {", "        \"event_id_a\": str(rows[0].event_id),", "        \"event_id_b\": str(rows[0].event_id),  # a == b", "        \"same_event\": True,", "        \"confidence\": 0.9,", "        \"explanation\": \"x\",", "    }", "    body = _valid_body(rows, [dup])", "    grader, _ = _grader(_response(body), _response(body))", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_foreign_duplicate_id_raises() -> None:", "    rows = [_row(\"create\"), _row(\"merge\")]", "    dup = {", "        \"event_id_a\": str(rows[0].event_id),", "        \"event_id_b\": str(uuid4()),  # not in the sample", "        \"same_event\": True,", "        \"confidence\": 0.9,", "        \"explanation\": \"x\",", "    }", "    body = _valid_body(rows, [dup])", "    grader, _ = _grader(_response(body), _response(body))", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_non_duplicate_pair_rejected() -> None:", "    rows = [_row(\"create\"), _row(\"merge\")]", "    dup = {", "        \"event_id_a\": str(rows[0].event_id),", "        \"event_id_b\": str(rows[1].event_id),", "        \"same_event\": False,  # only genuine duplicates may be listed", "        \"confidence\": 0.2,", "        \"explanation\": \"different events\",", "    }", "    body = _valid_body(rows, [dup])", "    grader, _ = _grader(_response(body), _response(body))", "    with pytest.raises(AIServiceException):", "        await grader.grade(prepared=_prepared(rows))", "", "", "# --------------------------------------- AC2: flagged findings need explanations --", "", "", "async def test_flagged_event_without_explanation_raises() -> None:", "    \"\"\"AC2: a flagged event (a bad merge) with a blank/whitespace explanation is", "    rejected -- the report must explain WHY the issue is problematic.\"\"\"", "    rows = [_row(\"merge\", docs=2)]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"merge_correct\"] = False  # flagged as a bad merge", "    body[\"per_event\"][0][\"explanation\"] = \"   \"  # whitespace-only", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"explanation\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_duplicate_pair_without_explanation_raises() -> None:", "    \"\"\"AC2: a duplicate pair is always a flag, so a blank explanation is rejected.\"\"\"", "    rows = [_row(\"create\"), _row(\"merge\", docs=2)]", "    dup = {", "        \"event_id_a\": str(rows[0].event_id),", "        \"event_id_b\": str(rows[1].event_id),", "        \"same_event\": True,", "        \"confidence\": 0.9,", "        \"explanation\": \"\",  # blank", "    }", "    body = _valid_body(rows, [dup])", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"explanation\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_repeated_duplicate_pair_rejected() -> None:", "    \"\"\"A duplicate pair listed twice -- or in both orders (a,b) and (b,a) -- is", "    rejected; it would inflate duplicate_pair_count and double-list the finding.\"\"\"", "    rows = [_row(\"create\"), _row(\"merge\", docs=2)]", "    dup = {", "        \"event_id_a\": str(rows[0].event_id),", "        \"event_id_b\": str(rows[1].event_id),", "        \"same_event\": True,", "        \"confidence\": 0.9,", "        \"explanation\": \"same real-world event\",", "    }", "    mirror = dict(dup)  # same undirected pair, reversed order", "    mirror[\"event_id_a\"], mirror[\"event_id_b\"] = dup[\"event_id_b\"], dup[\"event_id_a\"]", "    body = _valid_body(rows, [dup, mirror])", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"repeated duplicate pair\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_clean_event_may_omit_explanation() -> None:", "    \"\"\"A clean (valid, not-flagged) event may leave the explanation blank -- only", "    flagged findings must explain themselves.\"\"\"", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"explanation\"] = \"\"  # clean event, blank is acceptable", "    grader, _ = _grader(_response(body))", "", "    result = await grader.grade(prepared=_prepared(rows))", "    assert result.output.per_event[0].event_valid is True", "", "", "# --------------------------------------------- merge_correct required (F2) --", "", "", "async def test_merge_event_missing_merge_correct_raises() -> None:", "    \"\"\"F2: a merge-class event with a null merge_correct is a grader failure.", "", "    Otherwise the central merge-correctness check behind AC2 is silently dropped", "    while the report still delivers.", "    \"\"\"", "    rows = [_row(\"create\"), _row(\"merge\", docs=2)]", "    body = _valid_body(rows)", "    # rows[1] is the gradable (>=2 doc) merge event; blank out its verdict.", "    body[\"per_event\"][1][\"merge_correct\"] = None", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"merge_correct\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_merge_event_false_verdict_is_accepted() -> None:", "    \"\"\"A gradable merge (>=2 docs) with merge_correct=False (a flagged bad merge) is valid.\"\"\"", "    rows = [_row(\"merge\", docs=2)]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"merge_correct\"] = False", "    grader, _ = _grader(_response(body))", "", "    result = await grader.grade(prepared=_prepared(rows))", "    assert result.output.per_event[0].merge_correct is False", "", "", "async def test_create_event_null_merge_correct_is_accepted() -> None:", "    \"\"\"A create event legitimately keeps merge_correct=None (not applicable).\"\"\"", "    rows = [_row(\"create\")]", "    grader, _ = _grader(_response(_valid_body(rows)))", "", "    result = await grader.grade(prepared=_prepared(rows))", "    assert result.output.per_event[0].merge_correct is None", "", "", "async def test_create_event_with_merge_verdict_raises() -> None:", "    \"\"\"A create has no merge to judge, so a non-null merge_correct is a grader", "    contract violation. Rejecting it keeps a create from being counted and reported", "    as a bad merge (which would corrupt the AC2 signal).", "    \"\"\"", "    rows = [_row(\"create\"), _row(\"merge\", docs=2)]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"merge_correct\"] = False  # the create wrongly given a verdict", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"not applicable\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_one_document_merge_merge_correct_not_applicable() -> None:", "    \"\"\"A merge with <2 documents (an article_linked dup-evidence merge, or one left", "    by a tight doc cap) is still a merge-path event, but has nothing to compare, so", "    merge_correct MUST be null; a verdict on it is rejected. Event-validity still", "    applies -- only the merge-correctness call is not gradable on one document.", "    \"\"\"", "    rows = [_row(\"merge\", docs=1)]", "", "    # null accepted: nothing to compare on a single document.", "    ok_body = _valid_body(rows)", "    assert ok_body[\"per_event\"][0][\"merge_correct\"] is None", "    grader, _ = _grader(_response(ok_body))", "    result = await grader.grade(prepared=_prepared(rows))", "    assert result.output.per_event[0].merge_correct is None", "", "    # a non-null verdict on the same one-doc merge is rejected as not applicable.", "    bad_body = _valid_body(rows)", "    bad_body[\"per_event\"][0][\"merge_correct\"] = False", "    grader2, _ = _grader(_response(bad_body), _response(bad_body))  # both providers -> raises", "    with pytest.raises(AIServiceException, match=\"not applicable\"):", "        await grader2.grade(prepared=_prepared(rows))", "", "", "# ---------------------------------- entity-linkage plausibility (DAT-8294) --", "#", "# The fourth check. Its applicability rule mirrors merge-correctness exactly: the", "# verdict is REQUIRED where entity identity reached the grader and MUST be null", "# where none did. Both directions raise, because a null where evidence existed", "# silently drops AC3's central check and a verdict where none existed is a judgment", "# on evidence the grader never saw.", "", "", "async def test_entity_linkage_verdict_is_required_where_entities_reached_the_grader() -> None:", "    \"\"\"A null verdict on an event carrying entity identity is a grader failure.\"\"\"", "    rows = [_row(\"create\", entities=2), _row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"entity_linkage_plausible\"] = None", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"omitted entity_linkage_plausible\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_entity_linkage_verdict_where_no_entities_reached_the_grader_raises() -> None:", "    \"\"\"A verdict on an event with NO entity evidence is ungrounded and rejected.", "", "    The grader saw nothing to judge, so any answer it gives is invented -- and it", "    would reach the page as a real linkage finding.", "    \"\"\"", "    rows = [_row(\"create\", entities=1), _row(\"create\", entities=0)]", "    body = _valid_body(rows)", "    body[\"per_event\"][1][\"entity_linkage_plausible\"] = True", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"where no entity identity reached\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "@pytest.mark.parametrize(\"entity_count\", [0, 1, 5])", "@pytest.mark.parametrize(\"causes\", [frozenset(), frozenset({\"entity_cap\"})])", "def test_the_applicability_rule_is_the_complement_of_the_not_run_status(", "    entity_count, causes", ") -> None:  # noqa: ANN001", "    \"\"\"The verdict's applicability and the page's ``not_run`` status are ONE rule.", "", "    A drift here is invisible at the seam and loud on the page: the grader would", "    require a verdict on an event the report simultaneously describes as one the", "    entity check never ran on. Asserted as parity with", "    ``derive_entity_check_status`` rather than against a hardcoded expectation, so", "    a future change to what counts as ``not_run`` cannot leave the two disagreeing.", "    \"\"\"", "    row = _row(\"create\", entities=entity_count)", "    status = derive_entity_check_status(len(row.entities), causes)", "", "    assert entity_evidence_reached_grader(row) is (status != \"not_run\")", "", "", "async def test_a_plausible_verdict_is_accepted_and_does_not_flag() -> None:", "    rows = [_row(\"create\", entities=2)]", "    grader, _ = _grader(_response(_valid_body(rows)))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert result.output.per_event[0].entity_linkage_plausible is True", "    assert is_flagged(result.output.per_event[0]) is False", "", "", "async def test_an_implausible_verdict_is_accepted_and_flags_the_event() -> None:", "    \"\"\"R5: a false verdict must reach the ONE flag predicate, or it is not a flag.\"\"\"", "    rows = [_row(\"create\", entities=2)]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"entity_linkage_plausible\"] = False", "    body[\"per_event\"][0][\"entity_linkage_explanation\"] = \"Acme Corporation is a different company\"", "    grader, _ = _grader(_response(body))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert result.output.per_event[0].entity_linkage_plausible is False", "    assert is_flagged(result.output.per_event[0]) is True", "", "", "@pytest.mark.parametrize(\"explanation\", [None, \"\", \"   \"])", "async def test_an_implausible_verdict_without_an_explanation_is_rejected(explanation) -> None:  # noqa: ANN001", "    \"\"\"AC3: implausible linkage is flagged WITH an explanation. A flag with no", "    reason is not actionable, so the model itself refuses to hold one.", "    \"\"\"", "    rows = [_row(\"create\", entities=2)]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"entity_linkage_plausible\"] = False", "    body[\"per_event\"][0][\"entity_linkage_explanation\"] = explanation", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"schema validation\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_a_response_omitting_the_verdict_field_fails_schema_validation() -> None:", "    \"\"\"The field is REQUIRED and NULLABLE -- no default.", "", "    A default would let a stale canned response, or a live response from a model", "    that ignored the fourth question, validate as though the check had run.", "    \"\"\"", "    rows = [_row(\"create\", entities=2)]", "    body = _valid_body(rows)", "    del body[\"per_event\"][0][\"entity_linkage_plausible\"]", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"schema validation\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "async def test_the_fallback_enforces_the_same_linkage_contract_as_the_primary() -> None:", "    \"\"\"The fallback provider is a SECOND entry point into the same contract.", "", "    Its response is parsed by the same model and validated by the same semantics,", "    so a fallback body missing the verdict must fail exactly as a primary one does", "    -- not slip through because the primary already failed.", "    \"\"\"", "    rows = [_row(\"create\", entities=2)]", "    bad = _valid_body(rows)", "    del bad[\"per_event\"][0][\"entity_linkage_plausible\"]", "    primary_err = AIServiceException(\"503 upstream\", http_response_code=503)", "    grader, api_helper = _grader(primary_err, _response(bad))", "", "    with pytest.raises(AIServiceException, match=\"schema validation\"):", "        await grader.grade(prepared=_prepared(rows))", "    assert api_helper.execute_api_request.await_count == 2", "", "", "async def test_the_batch_is_still_graded_in_one_call_with_the_fourth_check() -> None:", "    \"\"\"No per-event LLM invocation crept in with the added question.\"\"\"", "    rows = [_row(\"create\", entities=2), _row(\"merge\", docs=2, entities=1), _row(\"create\")]", "    grader, api_helper = _grader(_response(_valid_body(rows)))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert len(result.output.per_event) == 3", "    assert api_helper.execute_api_request.await_count == 1", "", "", "async def test_entities_trimmed_to_nothing_make_the_verdict_not_applicable() -> None:", "    \"\"\"Applicability follows the PREPARED set, not the sampled one.", "", "    An event whose entities were all budget-trimmed carries no identity into the", "    prompt, so a verdict on it would be ungrounded even though the event really", "    does have entity links.", "    \"\"\"", "    rows = [_row(\"create\", entities=3, summary=\"x\" * 400)]", "    # Tight enough that every entity is trimmed, loose enough that the event", "    # survives: entities are the LAST evidence trimmed, so this is the budget at", "    # which the entity payload -- and only it -- goes.", "    grader, _ = _grader(max_input_chars=700)", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "    assert prepared.events[0].entities == []  # the trim actually happened", "", "    body = _valid_body(prepared.events)", "    assert body[\"per_event\"][0][\"entity_linkage_plausible\"] is None", "    grader2, _ = _grader(_response(body))", "    result = await grader2.grade(prepared=prepared)", "    assert result.output.per_event[0].entity_linkage_plausible is None", "", "    spurious = _valid_body(prepared.events)", "    spurious[\"per_event\"][0][\"entity_linkage_plausible\"] = True", "    grader3, _ = _grader(_response(spurious), _response(spurious))", "    with pytest.raises(AIServiceException, match=\"where no entity identity reached\"):", "        await grader3.grade(prepared=prepared)", "", "", "@pytest.mark.parametrize(", "    (\"entity_count\", \"verdict\", \"valid\"),", "    [", "        (2, True, True),", "        (2, False, True),", "        (2, None, False),  # invalid: evidence present, no verdict", "        (0, True, False),  # invalid: no evidence, verdict given", "        (0, False, False),  # invalid: no evidence, verdict given", "        (0, None, True),", "    ],", ")", "async def test_linkage_verdict_applicability_matrix(entity_count, verdict, valid) -> None:  # noqa: ANN001", "    \"\"\"{entities present, none present} x {true, false, null}, invalid rows included.\"\"\"", "    rows = [_row(\"create\", entities=entity_count)]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"entity_linkage_plausible\"] = verdict", "    if verdict is False:", "        body[\"per_event\"][0][\"entity_linkage_explanation\"] = \"wrong company linked\"", "", "    if valid:", "        grader, _ = _grader(_response(body))", "        result = await grader.grade(prepared=_prepared(rows))", "        assert result.output.per_event[0].entity_linkage_plausible is verdict", "    else:", "        grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "        with pytest.raises(AIServiceException):", "            await grader.grade(prepared=_prepared(rows))", "", "", "async def test_existing_flag_reasons_are_unchanged_by_the_fourth_check() -> None:", "    \"\"\"Pinned regression: the two pre-existing flag reasons flag exactly as before,", "    and a plausible linkage verdict adds nothing.", "    \"\"\"", "    invalid, bad_merge, clean = _row(\"create\"), _row(\"merge\", docs=2), _row(\"create\")", "    rows = [invalid, bad_merge, clean]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"event_valid\"] = False", "    body[\"per_event\"][0][\"explanation\"] = \"extraction artifact\"", "    body[\"per_event\"][1][\"merge_correct\"] = False", "    body[\"per_event\"][1][\"explanation\"] = \"two different events on one row\"", "    grader, _ = _grader(_response(body))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    flagged = {g.event_id for g in result.output.per_event if is_flagged(g)}", "    assert flagged == {invalid.event_id, bad_merge.event_id}", "", "", "async def test_the_completion_log_flagged_count_equals_the_rendered_flagged_count(", "    monkeypatch,  # noqa: ANN001", ") -> None:", "    \"\"\"The logs and the page must agree on a mixed run.", "", "    ``_log_complete`` restated the flagging rule inline instead of calling the", "    shared predicate, so the log and ``flagged_count`` reported different numbers", "    for the same run the moment a fourth flag reason existed. The run below holds", "    one entity-flagged event AND one invalid event, so a log that still counted only", "    the old reasons would report 1 against the page's 2.", "    \"\"\"", "    invalid, implausible, clean = _row(\"create\"), _row(\"create\", entities=2), _row(\"create\")", "    rows = [invalid, implausible, clean]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"event_valid\"] = False", "    body[\"per_event\"][0][\"explanation\"] = \"extraction artifact\"", "    body[\"per_event\"][1][\"entity_linkage_plausible\"] = False", "    body[\"per_event\"][1][\"entity_linkage_explanation\"] = \"an unrelated company\"", "    grader, _ = _grader(_response(body))", "", "    logged: list[dict] = []", "    monkeypatch.setattr(", "        qa_report_llm_mod.logger, \"info\", lambda event, **kw: logged.append({\"event\": event, **kw})", "    )", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    # What the CLI stores as metadata.flagged_count and the page renders as its", "    # \"Flagged events\" section -- the same predicate, summed the same way.", "    rendered_flagged_count = sum(1 for grade in result.output.per_event if is_flagged(grade))", "    complete = next(entry for entry in logged if entry[\"event\"] == \"qa_report_llm_complete\")", "", "    assert rendered_flagged_count == 2  # the invalid event AND the implausible linkage", "    assert complete[\"flagged\"] == rendered_flagged_count", "", "", "# ------------------------------------------ schema-error redaction (F4) --", "", "", "async def test_schema_validation_error_redacts_rejected_input() -> None:", "    \"\"\"F4: a schema-validation failure must NOT echo the rejected LLM values.", "", "    The raised AIServiceException carries redacted (type/loc/msg only) error", "    details -- never the raw ``ValidationError`` repr, which would leak the", "    offending response content (potentially event titles/summaries) into logs.", "    \"\"\"", "    marker = \"SENTINEL_LEAK_MARKER_DO_NOT_LOG\"", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"confidence\"] = marker  # not a float -> ValidationError", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException) as excinfo:", "        await grader.grade(prepared=_prepared(rows))", "", "    rendered = str(excinfo.value)", "    assert marker not in rendered  # the rejected value never surfaces", "    # Redacted details are still attached for diagnosis: locations, no input bodies.", "    errors = excinfo.value.variables[\"validation_errors\"]", "    assert errors and all(set(e) == {\"type\", \"loc\", \"msg\"} for e in errors)", "    assert all(\"input\" not in e and \"ctx\" not in e for e in errors)", "    assert any(\"confidence\" in e[\"loc\"] for e in errors)", "", "", "async def test_schema_validation_error_does_not_leak_via_exception_chain() -> None:", "    \"\"\"`from None` must break the __cause__ chain. The logging processor emits", "    error=repr(exc), cause=repr(exc.__cause__), and a full traceback stack; a chained", "    ValidationError would re-leak the rejected input the redaction strips out.", "    \"\"\"", "    import traceback as _traceback", "", "    marker = \"SENTINEL_LEAK_MARKER_DO_NOT_LOG\"", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"confidence\"] = marker  # not a float -> ValidationError", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException) as excinfo:", "        await grader.grade(prepared=_prepared(rows))", "", "    exc = excinfo.value", "    # cause = repr(exc.__cause__): must be None so the processor emits no cause.", "    assert exc.__cause__ is None", "    # error = repr(exc): the sanitized message, never the rejected value.", "    assert marker not in repr(exc)", "    # error.stack: the full traceback (which would render any chained cause).", "    stack = \"\".join(_traceback.format_exception(type(exc), exc, exc.__traceback__))", "    assert marker not in stack", "", "", "def test_system_prompt_covers_the_four_checks_and_their_gating() -> None:", "    \"\"\"Lock the grader rubric: event validity must require a REAL event (not noise /", "    extraction artifact), merge correctness gated on >=2 documents, cross-sample", "    duplicate detection, and (DAT-8294 AC3) entity-linkage plausibility.", "", "    The fourth check was unprotected: the schema half of the prompt and the", "    response model both survive deleting the RUBRIC, so canned grader responses", "    stay valid and every applicability / flagging test stays green while the model", "    is no longer told to judge linkage at all. The rubric markers below are", "    asserted SEPARATELY from the output-contract markers for exactly that reason --", "    deleting the instructions fails the first group, deleting the schema sentence", "    fails the second.", "    \"\"\"", "    from microservices.event_synthesis.services import qa_report_llm", "", "    prompt = qa_report_llm._SYSTEM_PROMPT.lower()", "    # (1) validity names a real event and excludes noise / extraction artifacts", "    assert \"real\" in prompt", "    assert \"artifact\" in prompt or \"noise\" in prompt", "    # (2) merge correctness, gated on >=2 documents", "    assert \"merge\" in prompt", "    assert \"2 or more\" in prompt or \"fewer than 2\" in prompt", "    # (3) cross-sample duplicate detection", "    assert \"duplicate\" in prompt", "    # (4) entity-linkage plausibility -- the INSTRUCTIONS. Each marker is a", "    #     distinct load-bearing clause, not a restatement of its neighbour: the", "    #     check has to be named, it has to say what is being judged, when to", "    #     return false, that a MISSING link is out of scope, and when the verdict", "    #     is not applicable. Dropping any one of them changes what the grader does.", "    for marker in (", "        \"entity-linkage plausibility\",  # the check is named", "        \"plausible participants\",  # what the model must judge", "        \"entity_linkage_plausible=false\",  # when to return a negative verdict", "        \"do not infer\",  # a missing link is not a finding", "        \"entity_linkage_explanation\",  # a negative verdict must be attributed", "    ):", "        assert marker in prompt, f\"linkage rubric lost its {marker!r} instruction\"", "    # Null-gating: no entities means nothing to judge, and the prompt must say so", "    # (it is the applicability rule `_validate_semantic` then ENFORCES).", "    assert \"set entity_linkage_plausible to null when the event's entities array is\" in prompt", "    assert \"empty\" in prompt", "", "    # (4) entity-linkage plausibility -- the required OUTPUT semantics. The verdict", "    #     is a mandatory per_event key, and the explanation is required and", "    #     non-empty exactly when the verdict is false (and null otherwise). Without", "    #     this the model may return a bare `false` the page cannot attribute.", "    assert \"entity_linkage_plausible (boolean or null)\" in prompt", "    assert (", "        \"entity_linkage_explanation \"", "        \"(string or null -- required and non-empty when entity_linkage_plausible is \"", "        \"false, otherwise null)\"", "    ) in prompt", "", "", "# ------------------------------------------ entity identity in the prompt (AC3)", "", "", "async def test_serialized_prompt_carries_each_entity_name_and_type() -> None:", "    \"\"\"AC3/R4: the grader must see each linked entity's NAME and TYPE.", "", "    Asserted against the exact ``_serialize`` payload -- the string actually sent", "    -- not against the DTO, because a field present on the model but excluded from", "    serialization would satisfy a model-level assertion while telling the grader", "    nothing.", "    \"\"\"", "    row = _row(\"create\", entities=2, entity_name=\"Northwind Traders\")", "    grader, _ = _grader()", "", "    serialized = grader._serialize(_prepared([row]))", "", "    assert '\"display_name\": \"Northwind Traders\"' in serialized", "    assert '\"entity_type\": \"CVW\"' in serialized", "    assert serialized.count('\"display_name\"') == 2", "", "", "async def test_entity_identity_reaches_the_grader_request_body() -> None:", "    \"\"\"The identity survives the whole path into the outgoing request body.\"\"\"", "    row = _row(\"create\", entities=1, entity_name=\"Globex Corporation\")", "    prepared = _prepared([row])", "    grader, api_helper = _grader(_response(_valid_body([row])))", "", "    await grader.grade(prepared=prepared)", "", "    body = _captured_body(api_helper)", "    sent = json.dumps(body)", "    assert \"Globex Corporation\" in sent", "", "", "# ------------------------------------------------------- prepare_input budget", "", "", "async def test_prepare_input_trims_evidence_without_dropping_events() -> None:", "    rows = [_row(\"create\", summary=\"s\", changes=8, docs=4, entities=6) for _ in range(2)]", "    grader, _ = _grader()", "    # Cap just above the fully-trimmed size (large placeholder truncated_fields", "    # so digit count can't undershoot) -> evidence trims, no whole event drops.", "    # A create keeps its doc floor of 1, so the trimmed baseline retains one doc.", "    stripped = [_row(\"create\", eid=r.event_id, docs=1) for r in rows]", "    stripped_size = len(", "        grader._serialize(", "            PreparedQAReportInput(events=stripped, dropped_event_ids=[], truncated_fields=9999)", "        )", "    )", "    grader._max_input_chars = stripped_size + 5", "", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "", "    assert prepared.dropped_event_ids == []  # no whole events dropped", "    assert len(prepared.events) == 2  # both events retained", "    assert prepared.truncated_fields > 0  # evidence was trimmed", "", "", "async def test_prepare_input_drops_trailing_events_preserving_class_coverage() -> None:", "    long_summary = \"x\" * 120", "    rows = [", "        _row(\"create\", summary=long_summary),", "        _row(\"merge\", summary=long_summary),", "        _row(\"create\", summary=long_summary),", "        _row(\"merge\", summary=long_summary),", "    ]", "    grader, _ = _grader()", "    # Cap = size of the expected 2-survivor / 2-dropped final state (tail dropped", "    # first: rows[3] then rows[2], preserving one create + one merge).", "    final = PreparedQAReportInput(", "        events=[rows[0], rows[1]],", "        dropped_event_ids=[rows[3].event_id, rows[2].event_id],", "        truncated_fields=0,", "    )", "    grader._max_input_chars = len(grader._serialize(final))", "", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "", "    assert len(prepared.dropped_event_ids) == 2", "    surviving_classes = {e.event_class for e in prepared.events}", "    assert surviving_classes == {\"create\", \"merge\"}  # coverage preserved", "    assert {str(e) for e in prepared.dropped_event_ids} == {", "        str(rows[2].event_id),", "        str(rows[3].event_id),", "    }", "", "", "async def test_prepare_input_raises_when_budget_unmeetable() -> None:", "    grader, _ = _grader(max_input_chars=10)", "    rows = [_row(\"create\", summary=\"x\" * 200)]", "    with pytest.raises(EventSynthesisConfigurationException):", "        grader.prepare_input(QAReportInput(events=rows))", "", "", "async def test_grade_validates_identity_against_trimmed_prepared_set() -> None:", "    long_summary = \"y\" * 120", "    rows = [", "        _row(\"create\", summary=long_summary),", "        _row(\"merge\", summary=long_summary),", "        _row(\"create\", summary=long_summary),", "    ]", "    # Prepare with a cap that drops one event, then grade only the survivors.", "    trim_grader, _ = _grader()", "    final = PreparedQAReportInput(", "        events=[rows[0], rows[1]], dropped_event_ids=[rows[2].event_id], truncated_fields=0", "    )", "    trim_grader._max_input_chars = len(trim_grader._serialize(final))", "    prepared = trim_grader.prepare_input(QAReportInput(events=rows))", "    assert len(prepared.events) == 2", "", "    grader, _ = _grader(_response(_valid_body(prepared.events)))", "    result = await grader.grade(prepared=prepared)", "    assert len(result.output.per_event) == 2", "", "", "async def test_budget_trim_preserves_min_docs_per_class() -> None:", "    \"\"\"Budget trimming never strips a merge below 2 docs (merge correctness needs", "    multiple documents to compare) or a create below 1; both events are retained.", "    \"\"\"", "    grader, _ = _grader()", "    merge = _row(\"merge\", summary=\"m\" * 40, docs=6, changes=6, entities=6)", "    create = _row(\"create\", summary=\"c\" * 40, docs=6, changes=6, entities=6)", "    rows = [merge, create]", "    # Cap at the floored state (merge=2 docs, create=1 doc, no changes/entities) plus", "    # slack; large placeholder truncated_fields so the digit count can't undershoot.", "    floored = PreparedQAReportInput(", "        events=[", "            _row(\"merge\", eid=merge.event_id, summary=\"m\" * 40, docs=2),", "            _row(\"create\", eid=create.event_id, summary=\"c\" * 40, docs=1),", "        ],", "        dropped_event_ids=[],", "        truncated_fields=9999,", "    )", "    grader._max_input_chars = len(grader._serialize(floored)) + 50", "", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "", "    assert prepared.dropped_event_ids == []  # both events retained, none dropped", "    by_id = {e.event_id: e for e in prepared.events}", "    assert len(by_id[merge.event_id].docs) >= 2  # merge doc floor held under trimming", "    assert len(by_id[create.event_id].docs) >= 1  # create doc floor held", "    assert prepared.truncated_fields > 0  # evidence was actually trimmed", "", "", "async def test_budget_trim_removes_globally_lowest_tier_doc_first() -> None:", "    \"\"\"Evidence trimming honors batch-wide priority: the globally lowest-tier", "    removable doc goes first, even when it sits on the NEWER event -- a higher-tier", "    doc on an older event is not removed before it (not strictly event-by-event).", "    \"\"\"", "    grader, _ = _grader()", "", "    def _merge_with_tiers(tiers: list[int]) -> QASampleRow:", "        row = _row(\"merge\")  # docs=0 default; set explicit best-first docs below", "        row.docs = [", "            QASampleDoc(document_id=1000 + n, source_tier=t, article_type=\"news\", title=f\"d{n}\")", "            for n, t in enumerate(tiers)  # best-first, so [-1] is the event's lowest", "        ]", "        return row", "", "    newest = _merge_with_tiers([5, 5, 1])  # index 0; its lowest removable doc = tier 1", "    oldest = _merge_with_tiers([5, 5, 5])  # index 1; its lowest removable doc = tier 5", "    rows = [newest, oldest]", "    # Budget = size after removing exactly ONE doc (the global lowest = newest's", "    # tier-1) + slack; placeholder truncated_fields so the digit count can't undershoot.", "    after = PreparedQAReportInput(", "        events=[_merge_with_tiers([5, 5]), _merge_with_tiers([5, 5, 5])],", "        dropped_event_ids=[],", "        truncated_fields=9999,", "    )", "    grader._max_input_chars = len(grader._serialize(after)) + 50", "", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "", "    by_id = {e.event_id: e for e in prepared.events}", "    # The global lowest (newest's tier-1) is removed; the older event's tier-5 docs", "    # are untouched -- proving global priority beats event iteration order.", "    assert [d.source_tier for d in by_id[newest.event_id].docs] == [5, 5]", "    assert [d.source_tier for d in by_id[oldest.event_id].docs] == [5, 5, 5]", "    assert prepared.dropped_event_ids == []", "", "", "# ------------------------------------------------ event-validity flag (AC2)", "", "", "async def test_invalid_event_with_explanation_is_accepted() -> None:", "    \"\"\"``event_valid=False`` is a verdict the report must carry, not a rejection.", "", "    Event validity is one of the three checks, and the only prior coverage of a", "    flagged event went through the merge axis (``merge_correct=False``).", "    \"\"\"", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"event_valid\"] = False", "    body[\"per_event\"][0][\"issues\"] = [\"extraction artifact, not a real event\"]", "    body[\"per_event\"][0][\"explanation\"] = \"summary is a headline template with no event\"", "    grader, _ = _grader(_response(body))", "", "    result = await grader.grade(prepared=_prepared(rows))", "", "    assert result.output.per_event[0].event_valid is False", "    assert result.output.per_event[0].issues == [\"extraction artifact, not a real event\"]", "", "", "async def test_invalid_event_without_explanation_raises() -> None:", "    \"\"\"The non-blank-explanation rule covers the validity axis, not just bad merges.\"\"\"", "    rows = [_row(\"create\")]", "    body = _valid_body(rows)", "    body[\"per_event\"][0][\"event_valid\"] = False", "    body[\"per_event\"][0][\"explanation\"] = \"  \"", "    grader, _ = _grader(_response(body), _response(body))  # both providers -> raises", "", "    with pytest.raises(AIServiceException, match=\"explanation\"):", "        await grader.grade(prepared=_prepared(rows))", "", "", "# ------------------------------- entity-loss provenance (DAT-8294 R7 / AC4) --", "", "", "async def test_trimming_an_entity_marks_that_event_with_the_budget_trim_cause() -> None:", "    \"\"\"The grader-phase loss path, named per event and per CAUSE.", "", "    A reader has to be able to tell budget pressure apart from the sampler's own", "    cap: one is fixed by raising ``max_input_chars`` (or lowering ``sample_size``),", "    the other by raising ``max_entities_per_event``. The old bare-``bool`` trim", "    signal could express neither.", "    \"\"\"", "    row = _row(\"create\", entities=4)", "    grader, _ = _grader()", "    stripped = _row(\"create\", eid=row.event_id, entities=1)", "    grader._max_input_chars = (", "        len(", "            grader._serialize(", "                PreparedQAReportInput(", "                    events=[stripped], dropped_event_ids=[], truncated_fields=9999", "                )", "            )", "        )", "        + 5", "    )", "", "    prepared = grader.prepare_input(QAReportInput(events=[row]))", "", "    assert prepared.entity_loss_causes[row.event_id] == frozenset({\"budget_trim\"})", "", "", "async def test_trimming_only_changes_and_docs_leaves_the_entity_causes_empty() -> None:", "    \"\"\"Cause discrimination, the negative half.", "", "    Changes and documents are trimmed BEFORE entities, so a batch that fits once", "    they are gone loses no entity evidence -- and must not be reported as though it", "    had. Without this, any trim at all would look like an entity loss.", "    \"\"\"", "    row = _row(\"merge\", docs=6, changes=6, entities=2)", "    grader, _ = _grader()", "    floored = _row(\"merge\", eid=row.event_id, docs=2, entities=2)", "    grader._max_input_chars = (", "        len(", "            grader._serialize(", "                PreparedQAReportInput(events=[floored], dropped_event_ids=[], truncated_fields=9999)", "            )", "        )", "        + 50", "    )", "", "    prepared = grader.prepare_input(QAReportInput(events=[row]))", "", "    assert prepared.truncated_fields > 0  # trimming really happened", "    assert len(prepared.events[0].entities) == 2  # entities untouched", "    assert prepared.entity_loss_causes == {}", "", "", "async def test_trim_returns_the_event_and_kind_it_removed_from() -> None:", "    \"\"\"``_trim_one_evidence`` names WHAT it removed and from WHERE, in trim order.\"\"\"", "    merge = _row(\"merge\", docs=3, changes=1, entities=1)", "    events = [merge]", "", "    first = QAReportGraderClient._trim_one_evidence(events)", "    second = QAReportGraderClient._trim_one_evidence(events)", "    third = QAReportGraderClient._trim_one_evidence(events)", "    fourth = QAReportGraderClient._trim_one_evidence(events)", "", "    assert (first.event_id, first.kind) == (merge.event_id, \"change\")", "    assert (second.event_id, second.kind) == (merge.event_id, \"document\")", "    assert (third.event_id, third.kind) == (merge.event_id, \"entity\")", "    assert fourth is None  # merge floor of 2 docs reached, nothing else removable", "", "", "async def test_entity_loss_causes_never_reach_the_grader_prompt() -> None:", "    \"\"\"Provenance is reader-facing and must stay out of the serialized payload.", "", "    ``_serialize`` is both the prompt and the budget measurement, so a field that", "    leaked into it would feed the grader bookkeeping it cannot use AND inflate the", "    payload the trimming loop exists to shrink.", "    \"\"\"", "    row = _row(\"create\", entities=1)", "    prepared = PreparedQAReportInput(", "        events=[row],", "        dropped_event_ids=[],", "        truncated_fields=0,", "        entity_loss_causes={row.event_id: frozenset({\"budget_trim\"})},", "    )", "", "    serialized = QAReportGraderClient._serialize(prepared)", "", "    assert \"entity_loss_causes\" not in serialized", "    assert \"budget_trim\" not in serialized", "", "", "# ---------------------------- budget regression under the enlarged payload --", "", "", "async def test_entities_are_still_the_last_evidence_trimmed_with_named_entities() -> None:", "    \"\"\"R6/AC4: identity made the entity payload bigger, not more expendable.", "", "    The trim order must stay change -> document -> entity. The control for this is", "    the mutation recorded in the PR body: reordering ``_trim_one_evidence`` to pop", "    entities first makes this test fail.", "    \"\"\"", "    merge = _row(\"merge\", summary=\"m\" * 40, docs=6, changes=6, entities=6, entity_name=\"N\" * 80)", "    grader, _ = _grader()", "    # A budget that forces SOME trimming but far from everything: entities must", "    # still be intact once the changes and the above-floor documents are gone.", "    after_changes_and_docs = _row(", "        \"merge\", eid=merge.event_id, summary=\"m\" * 40, docs=2, entities=6, entity_name=\"N\" * 80", "    )", "    grader._max_input_chars = (", "        len(", "            grader._serialize(", "                PreparedQAReportInput(", "                    events=[after_changes_and_docs], dropped_event_ids=[], truncated_fields=9999", "                )", "            )", "        )", "        + 50", "    )", "", "    prepared = grader.prepare_input(QAReportInput(events=[merge]))", "", "    survivor = prepared.events[0]", "    assert survivor.changes == []  # changes went first", "    assert len(survivor.docs) == 2  # documents went second, down to the merge floor", "    assert len(survivor.entities) == 6  # entities untouched: still last", "    assert prepared.entity_loss_causes == {}", "", "", "async def test_worst_case_supported_batch_fits_and_keeps_its_evidence_floors() -> None:", "    \"\"\"The supported maximum, measured rather than argued.", "", "    40 events x 10 entities x names at the cap is the largest entity payload the", "    configured caps allow -- but only if the names are the WORST the cap admits.", "    The cap counts python characters and the budget counts serialized JSON, so", "    plain letters understate the payload by ~5.9x (see ``_MAX_EXPANSION_NAME``);", "    a fixture built from letters would call itself a worst case while leaving the", "    real ceiling untested. Measured at 120k with maximum-expansion names: the raw", "    batch serializes to ~368k, and every one of the 40 events still reaches the", "    grader holding its document floor (60 documents) with 45 entities surviving.", "", "    What is asserted is CONCRETE retained evidence -- every merge keeps >= 2", "    documents, every create >= 1, and no event is dropped -- not \"it fits or it", "    fails closed\", which would pass either way and prove nothing. The retained", "    change and document counts are printed into the assertion messages so the cost", "    of the larger payload is a number in the record, not an assumption.", "    \"\"\"", "    # Guard the FIXTURE, not only the outcome: if this name ever drifts back to", "    # plain letters the test silently stops being a worst case, which is exactly", "    # the defect this fixture was rebuilt to close.", "    assert len(_MAX_EXPANSION_NAME) == 80, \"the name must sit exactly at the character cap\"", "    assert len(json.dumps(_MAX_EXPANSION_NAME, ensure_ascii=False)) == 482, (", "        \"the name must serialize to the escaping maximum, not to ~82 plain characters\"", "    )", "", "    rows = [", "        _row(", "            \"merge\" if i % 2 else \"create\",", "            summary=\"s\" * 2000,", "            docs=5,", "            entities=10,", "            changes=10,", "            entity_name=_MAX_EXPANSION_NAME,", "        )", "        for i in range(40)", "    ]", "    grader, _ = _grader(max_input_chars=120_000)", "", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "", "    retained_docs = sum(len(e.docs) for e in prepared.events)", "    retained_changes = sum(len(e.changes) for e in prepared.events)", "    retained_entities = sum(len(e.entities) for e in prepared.events)", "    assert prepared.dropped_event_ids == [], \"every event must still reach the grader\"", "    assert len(prepared.events) == 40", "    for event in prepared.events:", "        floor = 2 if event.event_class == \"merge\" else 1", "        assert len(event.docs) >= floor, (", "            f\"{event.event_class} kept {len(event.docs)} docs, floor {floor}; \"", "            f\"batch retained docs={retained_docs} changes={retained_changes} \"", "            f\"entities={retained_entities}\"", "        )", "    # Entities are trimmed last, so at this size some are necessarily gone -- but not", "    # all of them, and the events that lost any are named.", "    assert retained_entities > 0", "    assert set(prepared.entity_loss_causes.values()) <= {frozenset({\"budget_trim\"})}", "", "", "async def test_over_budget_batch_still_fails_closed_naming_the_env_knobs() -> None:", "    \"\"\"The enlarged payload must not weaken the fail-closed raise.", "", "    Sending an over-budget batch would fail at the provider with nothing useful in", "    the log; the raise names the two knobs an operator can actually turn.", "    \"\"\"", "    grader, _ = _grader(max_input_chars=50)", "    rows = [_row(\"create\", summary=\"x\" * 500, entities=10, entity_name=\"N\" * 80)]", "", "    with pytest.raises(EventSynthesisConfigurationException) as excinfo:", "        grader.prepare_input(QAReportInput(events=rows))", "", "    message = str(excinfo.value)", "    assert \"ESS_QA_REPORT_MAX_INPUT_CHARS\" in message", "    assert \"ESS_QA_REPORT_SAMPLE_SIZE\" in message", "", "", "async def test_budget_trim_causes_exclude_events_that_were_then_dropped() -> None:", "    \"\"\"A dropped event leaves no trim cause behind (PR #495 review).", "", "    ``entity_loss_causes`` is a public field on a returned model. An event can lose an", "    entity to the context budget and then be dropped wholesale by the same loop; its", "    id used to stay in the cause mapping, so a consumer reading the field directly", "    would count an entity loss for an event the report does not contain.", "", "    The budget here is deliberately tight enough to force BOTH phases -- entity trims", "    first, then whole-event drops -- because a batch that only trims can never produce", "    the orphan this guards against.", "    \"\"\"", "    rows = [", "        _row(", "            \"merge\" if i % 2 else \"create\",", "            summary=\"s\" * 2000,", "            docs=5,", "            entities=10,", "            changes=10,", "            entity_name=_MAX_EXPANSION_NAME,", "        )", "        for i in range(40)", "    ]", "    grader, _ = _grader(max_input_chars=30_000)", "", "    prepared = grader.prepare_input(QAReportInput(events=rows))", "", "    assert prepared.dropped_event_ids, \"fixture must actually drop events to be meaningful\"", "    surviving = {event.event_id for event in prepared.events}", "    orphaned = set(prepared.entity_loss_causes) - surviving", "", "    assert not orphaned, (", "        f\"{len(orphaned)} event(s) carry a budget_trim cause but were dropped from the \"", "        f\"prepared set; entity_loss_causes must describe only reported events\"", "    )", "    assert set(prepared.dropped_event_ids).isdisjoint(prepared.entity_loss_causes)"], "blocks": [{"start": 1, "end": 45, "label": "Imports and module setup"}, {"start": 46, "end": 60, "label": "def _params"}, {"start": 61, "end": 86, "label": "def _grader"}, {"start": 87, "end": 91, "label": "def _captured_body"}, {"start": 92, "end": 96, "label": "def _entity"}, {"start": 97, "end": 134, "label": "def _row"}, {"start": 135, "end": 138, "label": "def _prepared"}, {"start": 139, "end": 142, "label": "def _response"}, {"start": 143, "end": 146, "label": "def _raw_response"}, {"start": 147, "end": 172, "label": "def _valid_body"}, {"start": 173, "end": 194, "label": "def test_primary_success_parses_all_three_checks"}, {"start": 195, "end": 200, "label": "def _cut_off"}, {"start": 201, "end": 227, "label": "def test_a_repaired_primary_reply_falls_back_instead_of_being_graded"}, {"start": 228, "end": 236, "label": "def test_a_repaired_fallback_reply_fails_the_batch"}, {"start": 237, "end": 247, "label": "def test_a_fenced_but_valid_reply_is_still_accepted"}, {"start": 248, "end": 268, "label": "def test_a_raw_socket_timeout_falls_back_once_and_then_fails_the_batch"}, {"start": 269, "end": 292, "label": "def test_each_provider_gets_one_request_with_its_own_timeout"}, {"start": 293, "end": 304, "label": "def test_fallback_used_when_primary_raises"}, {"start": 305, "end": 324, "label": "def test_the_fallback_asks_for_a_reasoning_level_claude_accepts"}, {"start": 325, "end": 336, "label": "def test_the_primary_still_gets_the_configured_reasoning_level"}, {"start": 337, "end": 349, "label": "def test_double_failure_raises_ai_service_exception"}, {"start": 350, "end": 389, "label": "def test_provider_chain_request_payloads"}, {"start": 390, "end": 403, "label": "def test_sol_primary_double_failure_still_raises_for_the_degraded_path"}, {"start": 404, "end": 460, "label": "def test_from_config_wires_sol_primary_with_claude_fallback"}, {"start": 461, "end": 473, "label": "def test_out_of_range_confidence_rejected"}, {"start": 474, "end": 481, "label": "def test_missing_event_id_raises"}, {"start": 482, "end": 499, "label": "def test_unknown_event_id_raises"}, {"start": 500, "end": 508, "label": "def test_duplicate_event_id_raises"}, {"start": 509, "end": 523, "label": "def test_self_paired_duplicate_raises"}, {"start": 524, "end": 538, "label": "def test_foreign_duplicate_id_raises"}, {"start": 539, "end": 556, "label": "def test_non_duplicate_pair_rejected"}, {"start": 557, "end": 569, "label": "def test_flagged_event_without_explanation_raises"}, {"start": 570, "end": 586, "label": "def test_duplicate_pair_without_explanation_raises"}, {"start": 587, "end": 606, "label": "def test_repeated_duplicate_pair_rejected"}, {"start": 607, "end": 621, "label": "def test_clean_event_may_omit_explanation"}, {"start": 622, "end": 637, "label": "def test_merge_event_missing_merge_correct_raises"}, {"start": 638, "end": 648, "label": "def test_merge_event_false_verdict_is_accepted"}, {"start": 649, "end": 657, "label": "def test_create_event_null_merge_correct_is_accepted"}, {"start": 658, "end": 671, "label": "def test_create_event_with_merge_verdict_raises"}, {"start": 672, "end": 703, "label": "def test_one_document_merge_merge_correct_not_applicable"}, {"start": 704, "end": 714, "label": "def test_entity_linkage_verdict_is_required_where_entities_reached_the_grader"}, {"start": 715, "end": 729, "label": "def test_entity_linkage_verdict_where_no_entities_reached_the_grader_raises"}, {"start": 730, "end": 748, "label": "def test_the_applicability_rule_is_the_complement_of_the_not_run_status"}, {"start": 749, "end": 758, "label": "def test_a_plausible_verdict_is_accepted_and_does_not_flag"}, {"start": 759, "end": 772, "label": "def test_an_implausible_verdict_is_accepted_and_flags_the_event"}, {"start": 773, "end": 787, "label": "def test_an_implausible_verdict_without_an_explanation_is_rejected"}, {"start": 788, "end": 802, "label": "def test_a_response_omitting_the_verdict_field_fails_schema_validation"}, {"start": 803, "end": 820, "label": "def test_the_fallback_enforces_the_same_linkage_contract_as_the_primary"}, {"start": 821, "end": 831, "label": "def test_the_batch_is_still_graded_in_one_call_with_the_fourth_check"}, {"start": 832, "end": 859, "label": "def test_entities_trimmed_to_nothing_make_the_verdict_not_applicable"}, {"start": 860, "end": 888, "label": "def test_linkage_verdict_applicability_matrix"}, {"start": 889, "end": 907, "label": "def test_existing_flag_reasons_are_unchanged_by_the_fourth_check"}, {"start": 908, "end": 946, "label": "def test_the_completion_log_flagged_count_equals_the_rendered_flagged_count"}, {"start": 947, "end": 971, "label": "def test_schema_validation_error_redacts_rejected_input"}, {"start": 972, "end": 997, "label": "def test_schema_validation_error_does_not_leak_via_exception_chain"}, {"start": 998, "end": 1054, "label": "def test_system_prompt_covers_the_four_checks_and_their_gating"}, {"start": 1055, "end": 1072, "label": "def test_serialized_prompt_carries_each_entity_name_and_type"}, {"start": 1073, "end": 1088, "label": "def test_entity_identity_reaches_the_grader_request_body"}, {"start": 1089, "end": 1109, "label": "def test_prepare_input_trims_evidence_without_dropping_events"}, {"start": 1110, "end": 1138, "label": "def test_prepare_input_drops_trailing_events_preserving_class_coverage"}, {"start": 1139, "end": 1145, "label": "def test_prepare_input_raises_when_budget_unmeetable"}, {"start": 1146, "end": 1166, "label": "def test_grade_validates_identity_against_trimmed_prepared_set"}, {"start": 1167, "end": 1195, "label": "def test_budget_trim_preserves_min_docs_per_class"}, {"start": 1196, "end": 1235, "label": "def test_budget_trim_removes_globally_lowest_tier_doc_first"}, {"start": 1236, "end": 1254, "label": "def test_invalid_event_with_explanation_is_accepted"}, {"start": 1255, "end": 1269, "label": "def test_invalid_event_without_explanation_raises"}, {"start": 1270, "end": 1296, "label": "def test_trimming_an_entity_marks_that_event_with_the_budget_trim_cause"}, {"start": 1297, "end": 1322, "label": "def test_trimming_only_changes_and_docs_leaves_the_entity_causes_empty"}, {"start": 1323, "end": 1338, "label": "def test_trim_returns_the_event_and_kind_it_removed_from"}, {"start": 1339, "end": 1362, "label": "def test_entity_loss_causes_never_reach_the_grader_prompt"}, {"start": 1363, "end": 1396, "label": "def test_entities_are_still_the_last_evidence_trimmed_with_named_entities"}, {"start": 1397, "end": 1455, "label": "def test_worst_case_supported_batch_fits_and_keeps_its_evidence_floors"}, {"start": 1456, "end": 1472, "label": "def test_over_budget_batch_still_fails_closed_naming_the_env_knobs"}, {"start": 1473, "end": 1508, "label": "def test_budget_trim_causes_exclude_events_that_were_then_dropped"}], "lineCount": 1508, "sha256": "e0b41378f7bd8f0b009345af9239d78d8315b69bd468416b14da9e4e0a5d2d77", "endsWithNewline": true});
